func (this *Text) Cut() {
	this.CheckWidget()
	if (this.style & SINGLE) != 0 {
		if gtk.GTKGTK4 {
			gtk.GTK4Gtk_widget_activate_action(this.textHandle, gtk.OSAction_cut_clipboard, nil)
		} else {
			gtk.GTK3Gtk_editable_cut_clipboard(this.Handle)
		}
	} else {
		var clipboard int64
		if gtk.GTKGTK4 {
			clipboard = gtk.GTK4Gtk_widget_get_clipboard(this.Handle)
		} else {
			clipboard = gtk.GTK3Gtk_clipboard_get(int64(gtk.GDKGDK_NONE))
		}
		this.ClearSegments(true)
		gtk.GTKGtk_text_buffer_cut_clipboard(this.bufferHandle, clipboard, gtk.GTKGtk_text_view_get_editable(this.Handle))
		this.ApplySegments()
	}
}

