func (this *Text) eventWindow_() int64 {
	if (this.style & SINGLE) != 0 {
		var window int64 = this.Scrollable.paintWindow_()
		var children int64 = gtk.GDKGdk_window_get_children(window)
		if children != 0 {
			var childrenIterator int64 = children
			for {
				window = gtk.OSG_list_data(childrenIterator)
				cond211 := gtk.OSG_list_next(childrenIterator)
				childrenIterator = cond211
				if !((cond211) != 0) {
					break
				}
			}
		}
		gtk.OSG_list_free(children)
		return window
	} else {
		return this.impl.paintWindow_()
	}
}

func (this *Text) filterKey_(event int64) bool {
	var time int32 = gtk.GDKGdk_event_get_time(event)
	if time != this.lastEventTime {
		this.lastEventTime = time
		if this.imContext != 0 {
			if gtk.GTKGTK4 {
				return gtk.GTK4Gtk_im_context_filter_keypress(this.imContext, event)
			} else {
				return gtk.GTK3Gtk_im_context_filter_keypress(this.imContext, event)
			}
		}
	}
	this.gdkEventKey = event
	return false
}

func (this *Text) FixIM() {
	if this.gdkEventKey != 0 && this.gdkEventKey != -1 {
		if this.imContext != 0 {
			if gtk.GTKGTK4 {
				gtk.GTK4Gtk_im_context_filter_keypress(this.imContext, this.gdkEventKey)
			} else {
				gtk.GTK3Gtk_im_context_filter_keypress(this.imContext, this.gdkEventKey)
			}
			this.gdkEventKey = int64(-1)
			return
		}
	}
	this.gdkEventKey = int64(0)
}

func (this *Text) getBorderWidthInPixels_() int32 {
	this.CheckWidget()
	if (this.style & MULTI) != 0 {
		return this.Scrollable.getBorderWidthInPixels_()
	}
	if (this.style & BORDER) != 0 {
		return this.GetThickness(this.Handle).X
	}
	return 0
}

func (this *Text) GetCaretLineNumber() int32 {
	this.CheckWidget()
	if (this.style & SINGLE) != 0 {
		return 0
	}
	var position []int8 = make([]int8, TextITER_SIZEOF)
	var mark int64 = gtk.GTKGtk_text_buffer_get_insert(this.bufferHandle)
	gtk.GTKGtk_text_buffer_get_iter_at_mark(this.bufferHandle, position, mark)
	return gtk.GTKGtk_text_iter_get_line(position)
}

func (this *Text) GetCaretLocation() *Point {
	this.CheckWidget()
	if (this.style & SINGLE) != 0 {
		var index int32 = gtk.GTKGtk_editable_get_position(this.Handle)
		index = gtk.GTK3Gtk_entry_text_index_to_layout_index(this.Handle, index)
		var offset_x []int32 = make([]int32, 1)
		var offset_y []int32 = make([]int32, 1)
		gtk.GTK3Gtk_entry_get_layout_offsets(this.Handle, offset_x, offset_y)
		var layout int64 = gtk.GTK3Gtk_entry_get_layout(this.Handle)
		var pos gtk.PangoRectangle = gtk.PangoRectangle{}
		gtk.OSPango_layout_index_to_pos(layout, index, &pos)
		var x int32 = offset_x[0] + gtk.OSPANGO_PIXELS(pos.X) - this.impl.getBorderWidthInPixels_()
		var y int32 = offset_y[0] + gtk.OSPANGO_PIXELS(pos.Y)
		return NewPoint(x, y)
	} else {
		var position []int8 = make([]int8, TextITER_SIZEOF)
		var mark int64 = gtk.GTKGtk_text_buffer_get_insert(this.bufferHandle)
		gtk.GTKGtk_text_buffer_get_iter_at_mark(this.bufferHandle, position, mark)
		var rect gtk.GdkRectangle = gtk.GdkRectangle{}
		gtk.GTKGtk_text_view_get_iter_location(this.Handle, position, &rect)
		var x []int32 = make([]int32, 1)
		var y []int32 = make([]int32, 1)
		gtk.GTKGtk_text_view_buffer_to_window_coords(this.Handle, gtk.GTKGTK_TEXT_WINDOW_TEXT, rect.X, rect.Y, x, y)
		return NewPoint(x[0], y[0])
	}
}

func (this *Text) GetCaretPosition() int32 {
	this.CheckWidget()
	var result int32
	if (this.style & SINGLE) != 0 {
		var ptr int64
		if gtk.GTKGTK4 {
			ptr = gtk.GTKGtk_entry_buffer_get_text(this.bufferHandle)
		} else {
			ptr = gtk.GTK3Gtk_entry_get_text(this.Handle)
		}
		result = int32(gtk.OSG_utf8_offset_to_utf16_offset(ptr, int64(gtk.GTKGtk_editable_get_position(this.Handle))))
	} else {
		var position []int8 = make([]int8, TextITER_SIZEOF)
		var mark int64 = gtk.GTKGtk_text_buffer_get_insert(this.bufferHandle)
		gtk.GTKGtk_text_buffer_get_iter_at_mark(this.bufferHandle, position, mark)
		var zero []int8 = make([]int8, TextITER_SIZEOF)
		gtk.GTKGtk_text_buffer_get_iter_at_offset(this.bufferHandle, zero, 0)
		var ptr int64 = gtk.GTKGtk_text_buffer_get_text(this.bufferHandle, zero, position, true)
		result = int32(gtk.OSG_utf8_offset_to_utf16_offset(ptr, int64(gtk.GTKGtk_text_iter_get_offset(position))))
		gtk.OSG_free(ptr)
	}
	return this.UntranslateOffset(result)
}

func (this *Text) GetCharCount() int32 {
	this.CheckWidget()
	var result int32
	if (this.style & SINGLE) != 0 {
		if gtk.GTKGTK4 {
			result = gtk.GTK4Gtk_entry_get_text_length(this.Handle)
		} else {
			var str int64 = gtk.GTK3Gtk_entry_get_text(this.Handle)
			result = int32(gtk.OSG_utf16_strlen(str, int64(-1)))
		}
	} else {
		var startIter []int8 = make([]int8, TextITER_SIZEOF)
		var endIter []int8 = make([]int8, TextITER_SIZEOF)
		gtk.GTKGtk_text_buffer_get_bounds(this.bufferHandle, startIter, endIter)
		var ptr int64 = gtk.GTKGtk_text_buffer_get_text(this.bufferHandle, startIter, endIter, true)
		result = int32(gtk.OSG_utf16_strlen(ptr, int64(-1)))
		gtk.OSG_free(ptr)
	}
	return this.UntranslateOffset(result)
}
